) AS (
  VALUES 
    (314::BIGINT, 'De las profesoras mas incomodas de llevar, sus clases son aburridas y solo lee diapositivas, sus exámenes son complicados y largos, no hay nada bueno en las clases de ella y su asistente califica durísimo, no matriculen con ella !!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '82bace842215ac615d08d656b1af57b8fab638b2e6c5556faf50fd17bb711063'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'No le entendí nada, tuve que repetir curso, tarda mucho en entregar resultados de evaluaciones, como hasta la semana 6 te deja usar computadora, las anteriores tienes que programar en papel, es muy estricta calificando, si no lo haces como dice, está hecho con IA. No matricularía de nuevo con ella.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '0974cccddb71d7eb359c2ca362b24fa48d4c7ef0a6d3eeabd1266c5dba4c2995'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (314::BIGINT, 'La verdad ella asume que usted ya sabe todo, si usted no sabe quizas no sea la mejor opcion para usted.Ella es medio complicada de tratar y el asistente es aun peor, mejor evitela'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '2a1682947eb5c26ae15006f79f812f7ac5c3590b7f947b72ca0d0de9ae814ad7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'No matriculen con ella NUNCA, menos si son primer ingreso o no saben programar. Es demasiado egocéntrica y pasa rajando de que estudió en el UCR y el TEC, pero parece que eso no le sirvió de nada porque no sabe explicar. Aprovecha cada oportunidad para tratar mal a los estudiantes'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-12-24T00:00:00+00:00'::TIMESTAMPTZ, 'b00804e08efa1ca0b1a8b55af29fa923ac78e603245a508f2fc35968b629f773'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'NUNCA, NO LO HAGAN! no vale la pena leer más, simplemente es la PEOR profe que he visto. Todos mis compañeros han abandonado el curso. Deja demasiadas taeas, los examenes son imposibles de hacer en el tiempo. Y piensa que todo es con chagpt y pone 0 en trabajos de horas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-11-15T00:00:00+00:00'::TIMESTAMPTZ, '48657b6b5d00a18c9d63b9f87277c14dabe30cdc52b0259d0519a48c729a046e'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es totalmente INSOPORTABLE, hizo de mi semestre un estrés, es 0 comprensiva y es super egocéntrico, NO LA RECOMIENDO PARA NADA'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-11-11T00:00:00+00:00'::TIMESTAMPTZ, '94afc923d98d7bfec0481b325001ecaaadc2faff3e34a38f266e6d36363526cb'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No matriculen con esta profesora, al principio se trata de ver muy buena dice que ella asume que nadie sabe programar y que les va a ayudar y es la persona más falsa que hay tardamos 8 semanas en encender una computadora y estuvimos 7 semanas viendo diagramas de flujo di de baja el curso, no pudemas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'a298c61b5061ab4d78423e18a5f1ea082ab7e3f19806011859aef7d3190a2146'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'NO MATRICULEN, deberia de tener una nota mucho más baja, es una profesora terrible, sin duda que no merece ese puesto. Es demasiado pero exageradamente egocéntrica, juega de perfecta y que nunca se equivoca. Es imposible contradecirla. Deja muchas tareas super largas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-10-07T00:00:00+00:00'::TIMESTAMPTZ, '12139f0f07e4f2bd7833d7ceb4c482afea6a7c6e60eb094cb9781cff5a263696'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Se aprende bastante, deja varias prácticas pero suelen ser fáciles y rápidas, se aprende a programar desde cero, en algunos casos las instrucciones no son muy claras pero basta con preguntar, los proyectos los deja con suficiente tiempo. Creo que volvería a matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '9c1bea7a1dcb731a14abeb547c150fb7374ea6cf6651b61cf563fa6dd5a64716'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Si no sabes programar no matricules con ella, se quita el tiro de enseñar diciendo que hay que ser autodidactas, solo explica código en presentaciones que ya tiene hechas, explica ejemplos muy fáciles y en los exámenes pone retos con una dificultad mucho mayor a como lo explico'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-07-08T00:00:00+00:00'::TIMESTAMPTZ, '21b1e54f26856a8fe29d4b595937a50c8950533e87e3b807c72286560d078806'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La profesora es muy desordenada con las asignaciones, no sigue un cronograma y deja las evaluaciones en el tiempo que le convenga. No da rúbrica al estudiante y su redacción es ambigua en muchas ocasiones, generando confusión sobre lo que se debe hacer en cada trabajo. NO la recomiendo para intro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '62669b938ca9d120d187d63550cd4b4ae81798d2a54b899827c10a4288ae05e6'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'Deja trabajos poco claros y confusos. Califica duro pero es buena para enseñar.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9d7a9035961553134f9b0d5d104d3a3680876cdb117c72585a6de5bed43c8a56'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'Buena profesora, le interesa mucho que usted aprenda y siempre está en disposición de ayudar. Haga los trabajos a consciencia y le va ir muy bien. No da rúbricas de los trabajos al entregarlos, pero en caso de dudas o reclamos está dispuesta a negociar. Los trabajos lo revisa el asistente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '7089ab9a221f29d51b3ebf0c17dc3013a5e1fde70d6b22697c659f97195d15e6'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'MALA MAE , MALA CON GANAS'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '7ba4740d3b7c4627327d5b81b6773fb652d3328804db6932ca8ea6f9c62bce20'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No la recomiendo si no saben programar (como yo), no explica nada bien y las tareas son super largas para lo que vale. Ademas da muy poco tiempo para entregarlos Los examenes son super largos (practicamente no da tiempo de realizarlos). NO matricule con ella.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2024-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6e8a4bfc28365193674632c0cfed46898158953d4799944697c106bf02452057'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Si sabe programar preparece para que la profe le diga "No es como lo vimos en clase, no se evalua" y si no, mejor repita el curso'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c7727ea6dd3a13ad5bdf025d77e2571c34f3b8f0ee5cfb9280e26a5df99100b2'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'los trabajos son muy largos para lo que valen y en los examenes tambien los hace demasiado largos'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ce200d73b593dac656acdf338c40087ba069f7d667a42d8d65cee809d4d1dbea'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La verdad es que ella como persona no es mala, pero como profesora... Si tiene la oportunidad de no matricular con ella, no lo haga. Las explicaciones son muy confusas, además los trabajos son muy largos para el tiempo que ella asigna. Tarda demasiado para entregar trabajo, más de tres semanas o más'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '44ee81d4a97cf1310891ec4df3278f88f7ae04fe5731e50154390816c2f7b519'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La profe como persona es buena nota, pero a la hora de explicar sí le hace falta, no es muy clara y la da muy por encima. Los trabajos y exámenes son fáciles si usted ya sabía programar previamente'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases largas']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'eaab05b89b3d87637f6f7749531eff569e9b67359450ea763cba0e3eefdfb60b'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Una profesora que supone que todos saben programar, si le pide ayuda le va a decir exactamente lo mismo pero más por encima, sus explicaciones son largas y aburridas, si usted no lee mentes no tome este curso porque si no es como ella dice no sirve, hace las clases asincronicas innecesarias.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '18b3173e1a783ff60cea058db6b02fff3fac547b1a56ca62e71a033158ff3c93'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c07606a5578d1b6a61de7fefdaf29e783b2479378348f372060a4165c26ef731'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No volvería a matricular con esta profe, no explica para nada bien, dura 3 siglos revisando examenes, muchas tareas. Aparte de que el curso es dificil llevarlo con ella le aumenta la dificultad.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'd80b2a9de574d448d6f8459a579f52778fde49a38ce7317721e60e4348ae364b'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Una de las peores profesoras que me he topado, no explica bien ni la materia ni las asignaciones, si es por horario háganse un favor y matriculen con otro profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-05-09T00:00:00+00:00'::TIMESTAMPTZ, '8e9d629275c8585097dc109e49882ea77c528880599ea50539038a28fefa72c2'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es una intensa, el asistente ni que decir, si ese mae pudo cualquiera puede, y Dios guarde usted no haga el código exactamente igual a como ella lo hizo. No promete.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-02-20T00:00:00+00:00'::TIMESTAMPTZ, 'adee39ed3463cdf2ed8c3344a5fe58e61b507e3c83b7710d737deb251aff43fb'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Está profe me demuestra la clase de malura que tienen los profes de la escuela de computación, mala, ni ella sabe que está explicando, nombres, pase buenas noches.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-02-04T00:00:00+00:00'::TIMESTAMPTZ, '7fb683d984f109e046ad4354f08682ad01be7235bc74ffa93bb8851f9f65f633'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Es una profe muy poco organizada, deja muchas tareas y difíciles, califica cuando quiere, se atrasa en todo, molesta mucho para que participen y no explica muy bien, Si no está en clase ni espere que le responda porque nunca ve los mensajes. Busque otra opción'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f7509b126fbf6297b96f4e4d5162a491a0dfb462effe29e6998e22a05e02a530'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Esta roca es la peor docente que me he topado, se enrreda sola, exámenes duros, no ayuda en nada y para peores da notas cuanto le da la gana , al chile que decepción de docente.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b3d6871baa8ecfc5f3ac6fd4328ec6e90055ec1f1b2c5aaf61548df7941682aa'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'Si a usted le interesa ser QA, hágase un favor y no matricule con ella. Básicamente, no va a hacer nada de programación, todo es teoría de la cual la mitad no se entiende. Las instrucciones de los trabajos es lo peor, no se entiende ni ella en que es lo que quiere.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'c9285e8b8b41b4f5651fa0f55b543216d54e2cd8362f68ad999b17e5ca622c94'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'Está profe es mala CON M MAYÚSCULA'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2023-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'b462be2c097af9fe2f8c52058bd58254fc12de2fe88e39c324ab05597f0fe818'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No promete mae , esa vieja se enrreda sola y califica todo cuando le roque el cul*'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5a88c8bdd0e7880cc5a3a99f9cb55a4c2e2a4f9591b1b3c5a3ef57a995f2e1db'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a2654e3a9f84245c05a3458a283f3572942bf01419af0a8d26435eb90f97569d'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No mae , no promete ????????'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-03-08T00:00:00+00:00'::TIMESTAMPTZ, '16a262c463364e93b6ebb6e87eed9e93d4eecee277299ba9130185c1be2d66a7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Matrícule con ella si ya sabe programar, de lo contrario los cursos serán sumamente difíciles, y otra cosa, está profe es un completo desorden'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '15c6ea95018bcb9d8c1e78e2f502ba8b1aa75eb3262b882c1d57518d494bbc12'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Matricule con ella pesando que iba a ser buena profe pero para nada, explica muy mal en las clases, deja trabajos larguísimos y no tiene consideración por el estudiante, nunca esta dispuesta a dar tiempo extra para los trabajos tan largos que deja, eso sin mencionar lo incoherente que es.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2022-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'ed85af1fd8b869fc6b17c0aea5df613b8be5985498547aa6ff5034b78ca4d5e2'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Me dijeron que era la mejor opción si uno no sabía programar , pero no, no lo haga compa , está profe es un desorden, los exámenes son duros , califica cuando le da la gana y pide proyectos voladisimos, simplemente NO'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-10-22T00:00:00+00:00'::TIMESTAMPTZ, '541e14f20a61f1e77c2ad6abd10be969101b8e254ac356011b4dabbf747926c1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La profesora es amable y logra explicar de buena manera, tiene muchas incoherencias en los trabajos q deja por q cambia mucho las instrucciones, cuesta bastante consultar ayuda, no califica tan duro pero son demasiadas tareas. Creo q es una profe dedicada pero tiene varias deficiencias'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '560dc6e9f7751b04629053007423d7ec8cd8822065e649817cea508d45aff5e2'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd6992c82e15a85d53535d32bd8933a54dac5113b65cb7ae64c0639d9c90d8cb7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Si no sabe programar es la mejor opción porque empieza de cero pero si deja muchos trabajos y poco tiempo para hacerlos. A veces se contradice mucho'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ad848df313e67ae0af7c31fe32f7f87e527496d39b4c8ea4f17afb35487bc059'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Nunca volvería a llevar un curso con esta señora. Es súper intensa, cada rato se la pasa preguntando y si no sabe se enoja y te tira algún comentario. No se disfruta la clase por estar preocupado por si te va a preguntar algo o no. No da tiempo. Si es su primera vez programando no la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2022-05-12T00:00:00+00:00'::TIMESTAMPTZ, '06048d8b4cc22d5ba7e8d2c1517eeb0e56f29b87bf36b49649e0d760a0166fe5'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Demasiado intensa, muy poco tiempo para examenes'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-03-24T00:00:00+00:00'::TIMESTAMPTZ, '20d1a6595d62eb099aefc596fe0c6cb28a34211f08f00eed438af0500110672d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Excelente. Deja demasiado trabajopero eso ayuda a que uno entienda y le ayuda a subir la nota, las rúbricas son muy justas y lleva el curso sumamente ordenado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a89ebefe575a6c155aed8439ff72519e216b01674917c020e055c95565bf82e7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La clase no es tan clara, generalmente la materia nueva se ve en los últimos 15 minutos y deja tareas bastante pesadas en poco tiempo. Trabaja en parejas y da muy poco tiempo en los exámenes. Si no sabes nada de programación debes ponerle bastante, pero se pasa. Recomiendo entrar a consulta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '96d94299ec689811845907e1e249c4955e67c399f9c60e9942d3526ee910b642'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd9509b90503d6fcad2e08cc468c3a73dcf0969fa322a38092fbea3a57ac5d340'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-11-11T00:00:00+00:00'::TIMESTAMPTZ, '4f3c912ddbe39b1ddc5f93a114ddb4e1dd9085e2acaa724c0029e074df9009c4'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Excelente profesora, deja bastantes trabajos pero son fáciles y la mayoría es en parejas. Si usted no sabe nada de progra ella le enseña desde 0. Sin duda volvería a matricular con ella'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'bd326b4b17d1d1cd2cf89eaab08af94c7c35a349e020382b75db4a2e848ff073'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Esta profe se contradice mucho, siempre intenta hacer su clase como una familia. Si ya sabe programar un poco el curso de pasa solo, las primeras semanas puede meterse a zoom y dormir. Luego solo puede googlear lo que sea que haya dicho en la clase'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '3943d5843b0020575e37781cff890f8bbe733f149de37e255425fda0a279aa3e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Muchos trabajos, falta de comunicación en horario de no clase, examen medio difícil pero el estrés se lo puede llevar feo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Exámenes retadores']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '5816172e8cd3d6373b047dc9f08ab59f15de8643ff9b696ad70adbbded007a11'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Es la mejor si usted no sabe programar. Explica super claro y sencilllo. Deja muchas tareas, y casi todo es en parejas. Los exámenes no son difíciles, sólo no deje que se lo coman los nervios. Las progras las da con buen tiempo y no son difíciles. Cuesta mucho comunicarse con ella fuera de horario.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cf35991bf40903f37636d4883b0f61809546fbd0ddd32840bbc9d2f41c1c5178'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La recomiendo es una profesora muy buena, se interesa por los estudiantes, solo que deja muchas tareas, clafica duro y en cuanto a los examenes da poco tiempo, pero se puede negocias con ella si asi se le pide.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, '4e1fe1b02e1db1054c70aebcc5514efb2634e835f6863d503495b445f5c7a704'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Excelente profe, explica la materia muy clara. Deja muchos laboratorios pero eso ayuda a entender la materia. Los plazos de las evaluaciones son negociables. Se trabaja mucho en grupo y en parejas. Se aprende bastante'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-09T00:00:00+00:00'::TIMESTAMPTZ, '863aee2d2aafc9c8666c39f69471ab6b4be9414d959653a307452d7c77a6dce0'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La profe es muy buena si usted no tiene nada de bases en progra y quiere aprender, es un toque ruda con los trabajos y el tiempo en los exámenes pero si se habla con ella se pude llegar a un acuerdo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '96d8d20dfe96ed6c2403b23ba77d55aa9afbe0faba8b67718d117cb30b3c7de6'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'Es una muy buena profe, es una muy buena opción para iniciar a programar y explica todo muy bien. Deja tareas semanales y en los exámenes y quices da poco tiempo, lo cual lo hace un poco difícil pero si uno habla con ella es súper comprensiva. Trata de que uno siempre se sienta bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '37c0d5603dc28c889ef80d2307e0de09c3821ad3a281783b8984725eb22ebf90'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Es demasiado estricta, las tareas hay que rogar para que las califique, los exámenes son semi decentes, pero deja muchas tareas que quitan demasiado tiempo y no deja un tiempo moderado para realizarlas, sino dos o tres días'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '70b38c9c27ab4edd7879f3b3ab3fe13094e367379f2ec74a85c476459b0f5d4e'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La profe explica sumamente bien, sin embargo es estricta como muchas, si quiere aprender bastante matricule con ella; deja muchos laboratorios; pero posibles de hacer. Le gusta negociar, así que es muy flexible a la hora de entregar trabajos, sim embargo presiona mucho'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Inspirador']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4302533653169bedc661db753bd3f2c5ff63b4d4ed9116e7a8e02cd05c85f2ca'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'hay que ser muy lamesuelas, cada semana nos dejaba por lo menos dos laboratorios de progra que nos quitaban todo el tiempo del resto de los cursos, si se tiene mucha disponibilidad de tiempo no es tan pesado.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '9f196e34833b1a30ed135bb8dc5c2fc0a5667f9276357a73b8ef7e9014cc64b4'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Poca preparación, muy básico, se llega a un próximo curso de programación y hay deficiencias significativas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'd80cd8de082e4efcce1e94967125d4fa395043c409f5c58c7c2d6184b7b9408f'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es un curso que se podría dar con ejemplos y herramientas muy chivas. Pero ella no da clases, siempre hay que exponer y participar en todas las clases. Es un poco necia y la materia no queda clara. Siempre dice los mismos 5 ejemplos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, 'ea46e5569dc04a9537e03f1b8729e3fea913222c0f43480c444749f0e49a8b39'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'La profe es realmente buena, sabe dar el curso, lo que pasa es que no controla la cantidad de labores que debe manejar por lo que se excede con la cantidad de tareas. Se le saca el jugo a algunas, las clases son un poco pesadas pero entendibles. Me gustaría que fuera un poco más organizada nada más.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '65c25059cb5ef605523c5cf9877574969321e0cb9b4296110c68e833ee779310'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'Las clases son largas, las progras también pero son muy fáciles. Ella ayuda mucho y todo, al final del semestre nos entregó notas minutos antes de la entrega de actas y no aceptó quejas, dejó mucho para el final.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '27de41ab61b53129a60887f5e5b46af0c90e63c78c6469b161651efd5ce5985f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La profesora es buena, explica bien y definitivamente tomaría el curso con ella de nuevo, sin embargo da un tiempo mínimo para resolver exámenes y quices, los cuales califica bastante duro a veces. Deja muchas tareas, pero usted aprende como nunca con ellas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '9941b8ebda201721ecda34a02c3477509539d0bdfff75c14e237736ea0c65064'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'f32e42f4ecc8ca97d7b989979e16db485ad9b8461bf7c2f5ad1d26ed6a0219d9'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Pasamos 7 semanas atascados viendo material de Cursos Previos, se desapareció de existencia, dejó un proyecto de contenido que no vimos en clases (y que luego se quejó por cómo lo hicimos), ni siquiera terminó la primera mitad de los temas de Aseguramiento; una pérdida de tiempo. No ayuda en nada.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'd6e95629daafd49eec4df91dc97230eb63dada3e568f06e7fcc601c556f93938'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'Es buena profesora y más si usted no sabe programar desde antes aunque en modalidad virtual sentí cierto desorden en el curso. Es muy buena y si usted pone de su parte se aprende y se hacen amigos en el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '880d060171f8371a339e5f821db6bc0f1a5c296e83f32c68b8b0f9ed10c43c74'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Los exámenes y quices son complicados para el tiempo que da, y algunos ejercicios se los saca de la manga y a veces son imposibles Con esta profe se aprende demasiado (100% seguro), pero no recomiendo matricular con ella si cree que no tiene una capacidad de respuesta rápida y no es muy autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'd67678cbaebcc9d49eb8693ccdc612346ff07eca7964c9a10043b7eb1fcd9a22'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'No muy recomendable en virtual, deja demasiadas tareas y solicita tener camaras y micrófonos encendidos siempre, muy dura para calificar y bastante difícil con los quices'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '6f87b419af471216b3504fd2e77b1df1432033d43f6808999bc693a0bd966616'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Sabe mucho del área de QA, pero trae gente de afuera a que den la clase por ella. No está mal, pero se excedió demasiado en eso. Los reportes son fáciles, solo no entreguen una cochinada como los que se quejan que califica como quiere. Cuesta mucho contactarla porque no le da la gana responder.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '010c2e79efb4bac2e35a733fb133f5a34b1e851f6ab8d3dfbffc659e2ea265ea'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'La profe sabe explicar bien en mi opinión. Creo que puede mejorar la redacción de exámenes y laboratorios. Cuesta que responda los correos, sin embargo cuando uno pide ayuda ella la da. Disfruta dar clases y le importa la participación de los estudiantes. Yo la recomiendo como profe!'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '2dbef55b0752aec55f0efd74da0edc402bf7da5c02434f85ef4664e0f18b5b92'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Los correos y mensajes casi nunca los responde y la redacción en los trabajos y exámenes es un poco mala, pero nada del otro mundo. Por otro lado la profe es muy dedicada en su profesión y sí busca que el estudiante aprenda y mejore sus habilidades blandas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '41e9b032951a2d47c0ec5512ad89cb63588e63668c434d65e1531613b43b3fe5'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Fue con ganas el peor curso y la peor profe de toda la carrera. No contesta correos, nadie sabe cuando sube tareas, las califica como quiere. El curso se resume en que los estudiantes lean presentaciones, dos meses de charlas con cámara y que ella nos comparta tonteras en facebook. No se embarque!'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'a57276e0eaf28484cd062d7877f7784c4cc0c14287c7f6f9dc90e09d1d85b570'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'Cuesta que responda si tienes dudas con sus tareas que suelen ser confusas. Hace mucha énfasis en las habilidades blandas, pero se aprende bastante en la parte técnica y a desarrollar ciertas habilidades "importantes para la vida". Si no sabes programar, ella es una buena opción para comenzar.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '7ba6deb1e9a02861b5ac82aebde67ae0811b99f16fdaf2c37df735e1bc1ad2e1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Usted sale aprendiendo, pero más porque le toca ser autodidacta que por la profe. No deja claro las instrucciones de los exámenes, además de que tienen una alta dificultad para el tiempo del que se dispone.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'a63ca476c9d431021971864c5069ed6c2faf2a6147cfb6d2c3a1373db616a7b7'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Terrible profe, no se la juegue demasiado altarena y nunca contesta dudas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'd8ceec44634cb430ccfe45fc6ea6eaac7f838b1cc7e46c74d8391518730bf480'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Cero recomendada para la modalidad virtual, los exámenes son de tiempo muy limitado. Ambigua, es confusa a la hora de explicar y explica de mala manera, los laboratorios en su totalidad fui autodidacta. Posterior a un examen un estudiante le solicitó que resolviera el último ejercicio y no lo logró.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, '3b7868afe7d6457e2d75affcc5425969348859aa59cbc11a9288804bd248e540'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Las clases son escuchar a la profe leer presentaciones o pone a los estudiantes a dar las clases.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'ea0bf32312447636581295dd2b5a38d90db8764a5f116c18a8c3da187baeac10'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'Repetí Intro y Taller con ella, la primera vez lo llevé con un profe y me fue terrible. Con ella logré entender y mejorar mucho las notas. Explica de una manera clara y siempre hace práctica en clase, aunque tiene algunas deficiencias en especificaciones de exámenes y proyectos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'a2921190600b7f614221f8f01e919626df1e5ad5eab3553f091dec7d51205c12'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Deja siempre tarea, explica muy bien y no califica duro. Muy buena gente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'c8b3d8150c16d0be8adad4b270c85d064f2fdb8831709abe7112a2a33068950a'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Los exámenes y quices son increíblemente fáciles, los laboratorios tienen un poco más de complejidad pero la asistente los revisa super fácil, con que corra y cumpla con todos los requisitos le va bien. La profe es un sol y siempre está dispuesta a ayudar y a devolverse si alguien no entendió.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '2916dab2d02b8eef49216460dd80ec3390ee81747e440d62b9be143e4804e73e'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7536c3279b70c3df9d9ac281d439f0efdebbe8cd8ab7adbf5512417e1822bcdc'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'La verdad la profe es un poco pedorra, no deja en claro las instrucciones de los laboratorios y la asistente evalúa demasiado duro, además hay temas que no explica del todo bien.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '47c93a3ae5242ce329578507c278656e0517db0b77ce5b74518685583c5c6c73'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es excelente, por mucho la mejor. Es fácil pero también se aprende y es mejor llevar con ella que un profe con el que sea muy difícil pero no aprender tanto como se aprende con ella.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'fc86971daac06ed0564d96e619ed65857988da50fcc69b1603fabb9419175e96'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Excelente profe, da una verdadera "introducción" a lo que es progra y se preocupa por que todo el mundo entienda. El curso con ella es súper útil porque basa sus proyectos en ejemplos de la vida real que sirven en el futuro. No dude en matricular con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b83df9c3767fa53bc430c4d31c1009714df2db62489d81b2a11e46183b793258'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Excelente profe, se preocupa porque los estudiantes en verdad entiendan. Hay trabajos cortos todos los días que son muy útiles para llevar la materia al día.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '44d424aa7048b7b6c9a91f00acd5c514802cb8811697c2e65c56bcc0a34f31ee'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'La profe es super pura vida, hay quices todas las semanas pero son muy fáciles, los labs son un poco largos y exigentes pero te hacen llegar al examen super preparado, 100% recomendada'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'fe40a2735ee502bcce0b64c6927c2c64ffca1d514dc51b13c65b34985667e1df'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, '100% recomendada para aquellos que no saben programar. Las clases son un poco aburridas, pero el curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9c8f2076365c6e5570e4ca4c2dd872a2f4d1cb2932449618a3bc0a68dda586e9'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Al principio explica muy bien cómo funciona la lógica de programación con diagramas de flujo. Más adelante se hace más mecánico el curso. Los exámenes son easy, quices todas las semanas, a veces de teoría. Los labs son creativos y de copy & paste. Simpática.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '12c8dba09b2a6506ed121492c448980e8e175eb0af050c87cc9c7311ff2afef5'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Solo pasa hablando de habilidades blandas y ella no las tiene, al principio super bien con los diagramas de flujo pero luego deja de explicar por completo y pretende que uno aprenda a programar solo, califica rarísimo y no ayuda en nada, no la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '7f74a40a2acdc8b2f860f5f643027906ca2fae750a5c7d0cb3ad8f1d1dd8d720'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es una buena profesora en general, muy completa. La lógica de la programación queda bien explicada con los diagramas de flujo desde el principio. Si buscan aprender a programar, esta es su profesora.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '75500f1c0ec482bdda3a7bf19bb4c93b1dda92081f253c3b0c943a94e340308e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Es una profesora muy completa. Me gustó bastante que al principio deja muy claro como funciona la lógica de la programación con diagramas de flujo (esto no todos los profes lo hacen y luego programar se vuelve más difícil). Si lo que quiere es aprender mucho, lo mejor es que matricule con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '3a85dbd45b295981ce35c0ee7b0e16096b7df8a6b78405d53a93bf0ce76df70c'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es un poco desordenada y no explica bien, se salva que es un curso fácil. Creo que es de las mejores pero igual no la recomiendo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'acbfe3a2365d10d36fafd699692c7bc86de55f170202fc560256bffbec730f89'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Al inicio del curso va lento, pero se alanza al resto a mitad de semestre. Todos las tareas por mas cortas que sean son en grupos/parejas por lo que es mejor llevarlo con amigos si no es bueno socializando. los quices son fáciles pero son un poco mas de lo normal. Proyectos fáciles pero largos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '9667fe3a3d592435e553a8bc3de8794f54885e1e9edf29f95a12294354717618'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Excelente curso, te da una buena perspectiva sobre la vida laboral. Además, se esfuerza mucho para preparar charlas con empresas o temas de interés. Como parte negativa, a veces llega solo a leer presentaciones y deja muchos trabajos sin sentido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'd4bd2ba08b75b7ca0f80b924492139ee08c7b87ba858b9ae9785dc0ad35b4bf7'::TEXT, ARRAY[1056]::BIGINT[]),
    (314::BIGINT, 'La profesora se supone que es la "mejor" de la escuela de computación, pero a mi opinión es la peor profesora. Explica sumamente poco, falto a varias clases en el semestre, los laboratorios para la casa son extremadamente largos con un día de entrega, trata como niños de colegio y no contesta dudas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '18da1dcbdbcdf13081411f9c9bd7c9f9a3c0884e12cf76c5f832802350f13730'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Al inicio es un curso lento, para que todos entiendan a programar, despues de la primera tarea programada, empieza a ver todo mas rapido para poder ver todos los temas. Y LE ENCANTA el trabajo en equipo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2019-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'cf167d9f04b0585380adb87e346eaa346a719829c7502e274d2e8135424b936e'::TEXT, ARRAY[1020]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2019-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'fc0666841958a8a594cb667e6be4aa37e11ddd6c8287daecd8d2e3e318602998'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Cagado de risa, pero las clases son como ver pintura secarse de lo aburridas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-12-27T00:00:00+00:00'::TIMESTAMPTZ, '4a034a7a1bb0164ce032ad23a2ca4a7fbb9032031ad4793ccb0b59cd18e3823e'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La profe es un amor, los trabajos son un poco largo y generalmente para uno o dos días después, pero nada que no se logre. Es súper considerada y explica bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'c742bdb7d6a15f2760a5cde98e76a6e003437bd5bcf07f64e9cf5a00eafb40b1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Buena profesora, trabajos aveces muy largos dejados como para dos días o así, pero nada del otro mundo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1430bf9414abcdec8b5e8f7b2424699218b8b3534c92ab14dcfcf627b8a34a46'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Excelente profesora, la amé, deja todo muy claro y siempre se preocupa porque todos entiendan. Nunca deja nada muy difícil de hacer, las progras no soy muy complicadas y los laboratorios simples. Recomendadísima'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e15fa0939d7fa0be6e8ed4c6420f9b5c14e35c9bb074c40c4f9d5f59c889d975'::TEXT, ARRAY[1022]::BIGINT[]),
    (314::BIGINT, 'La güila es buena gente, eso no se lo voy a negar. Pero legalmente deja unos labs que son de dedicarle un huevazo de tiempo para que valgan tan poco en la nota. Los examenes son una culeada, asi intensa.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4c5f709badc46cffab3fc27a4d01469779b42bad758429013d664239381f8ada'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Los labs pueden tomar bastante tiempo, pero lo preparan muy bien para el examen. Realiza tres exámenes en el semestre y da recursos para repasar en la casa, los cuales en ocasiones son de bastante ayuda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a3266ea8d83d69fb7252dc45d163fbd2e42d414ac6b7970ec0d21ca28e20c39b'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Muy buena en comparación a otros profesores. Son 3 exámenes (otros hacen solo 2), y el primero es muy fácil. Los laboratorios son largos. Le da material para estudiar. Pasar depende de uno, pero no es complicado. La recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '3478d6228d2284dbf6a5d06ff27067e7335ecd886dcc2bf032c14e952752005c'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'b308066992ac302e19299a34e3ff79fdbd3ff2ce2373dbc2c3f97fc2185fb48c'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Explica muy bien y ayuda bastante si uno no entiende. Califica suave. La recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '9aad6bc581b8d863380d8d94c9f33c3751488153c9ec5a399ae4174b67b532e8'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La profesora explica bien y se aprende bastante si es que uno no sabe programar. Los lab son en parejas, los exámenes son muy sencillos, y deja varias tareas morales. La verdad la recomiendo porque fue excelente en su forma de trabajar,'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'dbaf2d3bff4174f531f0640ed511c87505139d488f2d864b6f4fc594f1eec90d'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Explica bien, solo que invierte mucho tiempo en diagramas de flujo, y cuando se empieza a programar es estricta en utilizar los formatos que ella indica.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2017-10-31T00:00:00+00:00'::TIMESTAMPTZ, '859d5be10f1df4428696507e19227ddb0166d6ae950f467ee5c662d6c8668a8d'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es una excelente profesora, le gusta que los estudiantes verdaderamente aprendan, dejan muchos trabajos pero ayuda para mejorar el entendimiento, súper recomendada, y como persona es muy buena gente, genera un ambiente de confianza en la clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-27T00:00:00+00:00'::TIMESTAMPTZ, '1b0f9802bf05f726147b9c33de99c79ab3ac2580cce5defd66d699fb0edc058e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'No da las instrucciones de lo que quiere Manda millones de correos Es super exigente'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '5abf109408943f65f8fe6ce7c2cc0ff71193f79084ea2e61d8340a3e28f75fa5'::TEXT, ARRAY[1673]::BIGINT[]),
    (314::BIGINT, 'No dude en matricular con ella! No hace el curso pesado y se aprende mucho (el curso tampoco es regalado), explica muy bien y se preocupa por el aprendizaje de los estudiantes. Se nota que le gusta enseñar y que tiene amor por la profesión.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1ccd69371444b48f284470b6bb39074ab888b83680b830ec8ebd75f95ac64f2a'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Excelente profe y persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'f93d84e438e379ffb414ed2040442072f9b33900733ebbe46969afefc62cdb1a'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'La profe quiere que uno aprenda de verdad la materia y más que todo que uno la aplique a la hora de los laboratorios. Los exámenes son sencillos en comparación con los labs que manda. Con ella es de comprender bien todo y preguntarle.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '133ec39f2452990a16542ece69d90dc553be747b431bb6eab2e10ddbabce6a6a'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Verano. Primera vez en el curso. La profe es buena y se preocupa por que el estudiante aprenda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'e1ad0d0fa2fbeaf1953b77b25a689318cf0199933be83ddfb2e513cd3c90388c'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Muy buena profe, explica muy bien, es buena gente y ayuda en todo lo que pueda. Los examenes son faciles y califica suave. Las progras de taller son muy logrables'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, '620e9bb6543bd0e66b59c6684d391be985c6b66d63fa4de08d0b2e41039afeef'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (314::BIGINT, 'Buena profe, le gusta mucho la participación en clase. El curso con ella requiere demasiado tiempo para la cantidad de créditos que son. Los asistentes los cuales califican los tareas, tienden a calificar mucho más duro que ella en los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'c114d56c9472f3dda0a8386be23677c9e0bbd80d6e07a92525b679df167d6750'::TEXT, ARRAY[1249]::BIGINT[]),
    (314::BIGINT, 'Es buena profe, deja muchas laboratorios y tareas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2016-09-27T00:00:00+00:00'::TIMESTAMPTZ, '59942275aeda55585cbf8261aa6c0c3337d88a858a45c83b220049685a3264c1'::TEXT, ARRAY[1030]::BIGINT[]),
    (314::BIGINT, 'Buena gente y buena profe'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8f33d7cba8cafefcb0569b9653ce65ab3293251ede7b9daabb40f4a55dcca8c7'::TEXT, ARRAY[1249]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
